/// Request structure for /listOutputs endpoint
#[derive(Debug, Deserialize)]
pub struct ListOutputsRequest {
    pub basket: String,
    pub tags: Option<Vec<String>>,
    #[serde(rename = "tagQueryMode")]
    pub tag_query_mode: Option<String>,  // "all" or "any"
    pub include: Option<String>,  // "locking scripts" or "entire transactions"
    #[serde(rename = "includeCustomInstructions")]
    pub include_custom_instructions: Option<bool>,
    #[serde(rename = "includeTags")]
    pub include_tags: Option<bool>,
    #[serde(rename = "includeLabels")]
    pub include_labels: Option<bool>,
    #[serde(rename = "includeOutputDescription")]
    pub include_output_description: Option<bool>,
    pub limit: Option<u32>,
    pub offset: Option<u32>,
}

/// Response structure for /listOutputs endpoint
#[derive(Debug, Serialize)]
pub struct ListOutputsResponse {
    #[serde(rename = "totalOutputs")]
    pub total_outputs: u32,
    pub outputs: Vec<WalletOutput>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub BEEF: Option<Vec<u8>>,  // BEEF as byte array (SDK expects number[])
}

/// Wallet output structure
#[derive(Debug, Serialize)]
pub struct WalletOutput {
    pub outpoint: String,  // "txid.vout"
    pub satoshis: i64,
    pub spendable: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    #[serde(rename = "lockingScript")]
    pub locking_script: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    #[serde(rename = "customInstructions")]
    pub custom_instructions: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tags: Option<Vec<String>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub labels: Option<Vec<String>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    #[serde(rename = "outputDescription")]
    pub output_description: Option<String>,
}

/// POST /listOutputs - BRC-100 Call Code 6
/// Lists spendable outputs within a specific basket
/// B5-T2-P1 (`P1-A10`): the rows a `p 1sat <scope>` view returns — storage basket `1sat`,
/// the axis tag (every scope but `all`) as a **mandatory** filter that `tagQueryMode` cannot
/// drop (BRC-165), and the caller's other tags narrowing further per `require_all`.
fn p1sat_rows(
    conn: &rusqlite::Connection,
    user_id: i64,
    axis_tag: Option<&str>,
    caller_tags: &[String],
    require_all: bool,
) -> rusqlite::Result<(i64, Vec<crate::database::Output>)> {
    let basket_id = crate::database::BasketRepository::new(conn).find_or_insert(crate::tokens::ONESAT_BASKET, user_id)?;
    let tag_repo = crate::database::TagRepository::new(conn);
    let output_repo = crate::database::OutputRepository::new(conn);
    let mut rows = match axis_tag {
        None => output_repo.get_spendable_by_basket(basket_id)?,
        Some(axis) => match tag_repo.find_tag_ids(&[axis.to_string()])?.as_slice() {
            [] => Vec::new(),
            ids => output_repo.get_spendable_by_basket_with_tags(basket_id, Some(ids), false)?,
        },
    };
    let extras: Vec<String> = caller_tags.iter().map(|t| t.trim().to_lowercase())
        .filter(|t| Some(t.as_str()) != axis_tag).collect();
    // `all`: every caller tag. `any`: the axis tag (itself a caller tag) already satisfies
    // it; with no axis (`p 1sat all`), at least one caller tag.
    if !extras.is_empty() && (require_all || axis_tag.is_none()) {
        rows.retain(|o| {
            let tags = o.output_id.and_then(|id| tag_repo.get_tags_for_output(id).ok()).unwrap_or_default();
            if require_all { extras.iter().all(|e| tags.contains(e)) } else { extras.iter().any(|e| tags.contains(e)) }
        });
    }
    Ok((basket_id, rows))
}

/// B5-T2-P1 (`P1-A9`): rows internalized before the BRC-37 fix stored a sender's
/// `customInstructions` wrapped as `{"type":"basket_insertion","basket":…,"appData":<ci>}`.
/// Hand back the sender's original string (`None` when they sent none); any other stored
/// value — including every row written since — is returned unchanged.
pub(crate) fn legacy_basket_insertion_ci(stored: &str) -> Option<String> {
    let Ok(serde_json::Value::Object(m)) = serde_json::from_str::<serde_json::Value>(stored) else {
        return Some(stored.to_string());
    };
    let wrapped = m.get("type").and_then(|t| t.as_str()) == Some("basket_insertion")
        && m.contains_key("basket")
        && m.keys().all(|k| matches!(k.as_str(), "type" | "basket" | "appData"));
    if !wrapped {
        return Some(stored.to_string());
    }
    match m.get("appData") {
        Some(serde_json::Value::String(ci)) => Some(ci.clone()),
        Some(other) => Some(other.to_string()),
        None => None,
    }
}

pub async fn list_outputs(
    state: web::Data<AppState>,
    http_req: HttpRequest,
    body: web::Bytes,
) -> HttpResponse {
    log::info!("📋 /listOutputs called");

    // B5-T2-P1 (`P1-A10`/`P1-A11`): a `p 1sat <scope>` basket is a BRC-165 view of storage
    // basket `1sat`, gated by its own view grant (`p 1sat all`, or `p 1sat <scope> <value>`;
    // `all` covers the others) — payment grants never cover it. `p 1sat id` needs no grant
    // (BRC-165 "MUST NOT require grant all"). Malformed requests are refused here.
    let view = peek_scoped_grant_scope_basket(&body)
        .map(|b| {
            let tags: Vec<String> = serde_json::from_slice::<serde_json::Value>(&body).ok()
                .and_then(|j| j.get("tags").and_then(|t| t.as_array()).map(|a|
                    a.iter().filter_map(|v| v.as_str().map(str::to_string)).collect()))
                .unwrap_or_default();
            crate::tokens::p1sat_view(&b, &tags)
        })
        .unwrap_or(crate::tokens::P1satView::NotP1sat);
    if let crate::tokens::P1satView::Reject(msg) = &view {
        return HttpResponse::BadRequest().json(serde_json::json!({
            "error": msg, "code": "ERR_INVALID_BASKET_NAME"
        }));
    }
    if let crate::tokens::P1satView::View { grant_key: Some(key), .. } = &view {
        let outcome = crate::permission_service::dispatch_scoped_grant(
            &state.permission,
            &state.database,
            state.current_user_id,
            &http_req,
            &body,
            "/listOutputs",
            crate::permission_service::ScopedCall::Basket { basket: key, access: "read" },
        );
        if let crate::permission_service::GateOutcome::EarlyReturn(resp) = outcome {
            return resp;
        }
    }

    // Phase 2.6-D scoped-grant gate (basket access, read).
    if let (crate::tokens::P1satView::NotP1sat, Some(basket_name)) = (&view, peek_scoped_grant_scope_basket(&body)) {
        let outcome = crate::permission_service::dispatch_scoped_grant(
            &state.permission,
            &state.database,
            state.current_user_id,
            &http_req,
            &body,
            "/listOutputs",
            crate::permission_service::ScopedCall::Basket {
                basket: &basket_name,
                access: "read",
            },
        );
        if let crate::permission_service::GateOutcome::EarlyReturn(resp) = outcome {
            return resp;
        }
    }

    // Defense-in-depth: verify domain is approved
    {
        let db = state.database.lock().unwrap();
        if let Err(resp) = check_domain_approved(&http_req, db.connection(), state.current_user_id) {
            return resp;
        }
    }

    // Parse the body once the gate has cleared.
    let req: ListOutputsRequest = match serde_json::from_slice(&body) {
        Ok(r) => r,
        Err(e) => {
            log::error!("   Failed to parse ListOutputsRequest: {}", e);
            return HttpResponse::BadRequest().json(serde_json::json!({
                "error": format!("Invalid request: {}", e)
            }));
        }
    };

    log::info!("   Basket: {}", req.basket);
    log::info!("   Tags: {:?}", req.tags);
    log::info!("   Tag query mode: {:?}", req.tag_query_mode);

    // Phase 2.6-D D.3: protected basket guardrail (defense-in-depth in the
    // endpoint itself). The engine ALSO blocks but the endpoint enforces too.
    // BRC-100 spec also prohibits "default" as a user-facing listOutputs target.
    // B5-T2-P1: BRC-99 — a `p <scheme>` basket the wallet does not implement is refused
    // (until now it was silently created and listed as empty).
    if matches!(view, crate::tokens::P1satView::NotP1sat) && req.basket.trim().to_lowercase().starts_with("p ") {
        return HttpResponse::BadRequest().json(serde_json::json!({
            "error": format!("Basket '{}' names a permission scheme this wallet does not implement (BRC-99)", req.basket),
            "code": "ERR_INVALID_BASKET_NAME"
        }));
    }

    // B5-T2-P1: `1sat` is read only through `p 1sat <scope>` (BRC-165); `bsv21` (no
    // view scheme of its own) is readable but always prompts — the gate above forces it.
    let requested = req.basket.trim().to_lowercase();
    let routed = matches!(view, crate::tokens::P1satView::View { .. });
    if !routed && crate::permission_service::is_protected_basket(&requested) && requested != crate::tokens::BSV21_BASKET {
        let error = if requested == crate::tokens::ONESAT_BASKET {
            "Basket '1sat' is read through 'p 1sat <scope>' (BRC-165)"
        } else {
            "Basket name is reserved and cannot be accessed via listOutputs"
        };
        return HttpResponse::BadRequest().json(serde_json::json!({ "error": error }));
    }

    // Phase 4D: Get database - scoped to drop lock before BEEF building (which re-locks internally)
    let (basket_id, filtered_outputs) = if let crate::tokens::P1satView::View { axis_tag, .. } = &view {
        let db = state.database.lock().unwrap();
        match p1sat_rows(db.connection(), state.current_user_id, axis_tag.as_deref(),
                         req.tags.as_deref().unwrap_or(&[]), req.tag_query_mode.as_deref() == Some("all")) {
            Ok(r) => r,
            Err(e) => {
                log::error!("   Failed to query 1sat view: {}", e);
                return HttpResponse::InternalServerError().json(serde_json::json!({
                    "error": format!("Failed to query outputs: {}", e)
                }));
            }
        }
    } else {
        let db = state.database.lock().unwrap();
        let basket_repo = crate::database::BasketRepository::new(db.connection());
        let tag_repo = crate::database::TagRepository::new(db.connection());
        let output_repo = crate::database::OutputRepository::new(db.connection());

        // Resolve basket (find or create)
        let basket_id = match basket_repo.find_or_insert(&req.basket, state.current_user_id) {
            Ok(id) => id,
            Err(e) => {
                log::error!("   Failed to find or create basket: {}", e);
                return HttpResponse::InternalServerError().json(serde_json::json!({
                    "error": format!("Failed to resolve basket: {}", e)
                }));
            }
        };

        // Resolve tags if provided
        let tag_ids = if let Some(tags) = &req.tags {
            if tags.is_empty() {
                Vec::new()
            } else {
                match tag_repo.find_tag_ids(tags) {
                    Ok(ids) => ids,
                    Err(e) => {
                        log::error!("   Failed to resolve tags: {}", e);
                        return HttpResponse::InternalServerError().json(serde_json::json!({
                            "error": format!("Failed to resolve tags: {}", e)
                        }));
                    }
                }
            }
        } else {
            Vec::new()
        };

        // Phase 4D: Query from outputs table (PRIMARY SOURCE) with SQL-based tag filtering
        let tag_query_mode = req.tag_query_mode.as_deref().unwrap_or("any");
        let require_all_tags = tag_query_mode == "all";

        let filtered_outputs = if !tag_ids.is_empty() {
            // Use efficient SQL-based tag filtering
            match output_repo.get_spendable_by_basket_with_tags(basket_id, Some(&tag_ids), require_all_tags) {
                Ok(outputs) => outputs,
                Err(e) => {
                    log::error!("   Failed to query outputs with tags: {}", e);
                    return HttpResponse::InternalServerError().json(serde_json::json!({
                        "error": format!("Failed to query outputs: {}", e)
                    }));
                }
            }
        } else {
            // No tags - just query by basket
            match output_repo.get_spendable_by_basket(basket_id) {
                Ok(outputs) => outputs,
                Err(e) => {
                    log::error!("   Failed to query outputs: {}", e);
                    return HttpResponse::InternalServerError().json(serde_json::json!({
                        "error": format!("Failed to query outputs: {}", e)
                    }));
                }
            }
        };

        (basket_id, filtered_outputs)
    }; // db lock dropped here - safe for BEEF building to re-lock

    // Apply pagination
    let offset = req.offset.unwrap_or(0) as usize;
    let limit = req.limit.unwrap_or(10).min(10000) as usize;
    let total_outputs = filtered_outputs.len();
    let paginated_outputs: Vec<_> = filtered_outputs.into_iter()
        .skip(offset)
        .take(limit)
        .collect();

    log::info!("   Found {} outputs (total: {})", paginated_outputs.len(), total_outputs);

    // Build response outputs
    let include_locking_scripts = req.include.as_deref() == Some("locking scripts");
    let include_transactions = req.include.as_deref() == Some("entire transactions");
    let include_custom_instructions = req.include_custom_instructions.unwrap_or(false);
    let include_tags = req.include_tags.unwrap_or(false);
    let include_labels = req.include_labels.unwrap_or(false);
    let include_output_description = req.include_output_description.unwrap_or(false);

    let mut outputs = Vec::new();
    let mut beef = crate::beef::Beef::new();

    // Create HTTP client for BEEF building (if needed) with timeout to prevent hanging
    let client = if include_transactions {
        Some(reqwest::Client::builder()
            .timeout(crate::services::CallClass::IndexerBulk.timeout())
            .build()
            .unwrap_or_else(|_| reqwest::Client::new()))
    } else {
        None
    };

    for db_output in &paginated_outputs {
        // Phase 4D: Output uses Option<String> for txid
        let txid = db_output.txid.as_deref().unwrap_or("");
        let outpoint = format!("{}.{}", txid, db_output.vout);

        // Get tags and labels if requested (brief lock, released before BEEF building)
        let (tags, labels) = if include_tags || include_labels {
            let db = state.database.lock().unwrap();
            let tag_repo = crate::database::TagRepository::new(db.connection());

            let tags = if include_tags {
                if let Some(output_id) = db_output.output_id {
                    tag_repo.get_tags_for_output(output_id).ok()
                        .filter(|t| !t.is_empty())
                } else {
                    None
                }
            } else {
                None
            };

            let labels = if include_labels {
                tag_repo.get_labels_for_txid(txid).ok()
                    .filter(|l| !l.is_empty())
            } else {
                None
            };

            (tags, labels)
        } else {
            (None, None)
        };

        let output = WalletOutput {
            outpoint,
            satoshis: db_output.satoshis,
            spendable: true,  // All returned outputs are spendable (filtered by get_spendable_*)
            locking_script: if include_locking_scripts {
                // B5-T1-P4: through the accessor — a script above the inline cap is
                // read from its raw parent, not returned as missing.
                let db = state.database.lock().unwrap();
                crate::database::OutputRepository::new(db.connection())
                    .locking_script_for(db_output)
                    .map(|bytes| hex::encode(bytes))
            } else {
                None
            },
            custom_instructions: if include_custom_instructions {
                db_output.custom_instructions.as_deref().and_then(legacy_basket_insertion_ci)
            } else {
                None
            },
            tags,
            labels,
            output_description: if include_output_description {
                db_output.output_description.clone()
            } else {
                None
            },
        };

        // Build BEEF if requested
        if include_transactions {
            // Check if transaction already in BEEF (deduplication)
            if beef.find_txid(txid).is_none() {
                // Services is always available on AppState; no Option wrapping needed
                if let Err(e) = crate::beef_helpers::build_beef_for_txid(
                    txid,
                    &mut beef,
                    &state.database,
                    &state.services, &*state.chain_tracker,
                ).await {
                    log::warn!("   ⚠️  Failed to build BEEF for transaction {}: {}, continuing...", txid, e);
                    // Continue processing other outputs even if one fails
                }
            } else {
                log::info!("   ⏭️  Transaction {} already in BEEF, skipping", txid);
            }
        }

        outputs.push(output);
    }

    // Serialize BEEF if built (V1 format for overlay compatibility)
    let beef_bytes = if include_transactions && !beef.transactions.is_empty() {
        match beef.to_v1_bytes() {
            Ok(bytes) => Some(bytes),
            Err(e) => {
                log::warn!("   Failed to serialize BEEF: {}", e);
                None
            }
        }
    } else {
        None
    };

    HttpResponse::Ok().json(ListOutputsResponse {
        total_outputs: total_outputs as u32,
        outputs,
        BEEF: beef_bytes,
    })
}

/// GET /wallet/tokens — List all token outputs (non-default, non-certificate baskets)
///
/// Returns all spendable outputs from app-created baskets, grouped by basket name.
/// Used by the Tokens tab in the wallet UI.
pub async fn list_token_outputs(
    state: web::Data<AppState>,
) -> HttpResponse {
    let db = state.database.lock().unwrap();
    let conn = db.connection();

    // Query all spendable outputs in non-default, non-certificate baskets.
    // For wallet-backup basket, only show the PushDrop (vout=0), not the marker (vout=1).
    let mut stmt = match conn.prepare(
        "SELECT o.outputId, o.txid, o.vout, o.satoshis, o.output_description,
                o.created_at, o.spendable, b.name as basket_name
         FROM outputs o
         JOIN output_baskets b ON o.basket_id = b.basketId
         WHERE o.user_id = ?1 AND o.spendable = 1
           AND b.name NOT IN ('default', 'identity_certificates')
           AND (b.is_deleted IS NULL OR b.is_deleted = 0)
           AND NOT (b.name = 'wallet-backup' AND o.vout = 1)
         ORDER BY b.name, o.created_at DESC"
    ) {
        Ok(s) => s,
        Err(e) => {
            return HttpResponse::InternalServerError().json(serde_json::json!({
                "error": format!("Database error: {}", e)
            }));
        }
    };

    let rows: Vec<serde_json::Value> = match stmt.query_map(
        rusqlite::params![state.current_user_id],
        |row| {
            Ok(serde_json::json!({
                "outputId": row.get::<_, i64>(0)?,
                "txid": row.get::<_, Option<String>>(1)?,
                "vout": row.get::<_, i32>(2)?,
                "satoshis": row.get::<_, i64>(3)?,
                "description": row.get::<_, Option<String>>(4)?,
                "createdAt": row.get::<_, i64>(5)?,
                "spendable": row.get::<_, bool>(6)?,
                "basket": row.get::<_, String>(7)?,
            }))
        },
    ) {
        Ok(mapped) => mapped.filter_map(|r| r.ok()).collect(),
        Err(_) => vec![],
    };

    // Fetch tags for each output
    let tag_repo = crate::database::TagRepository::new(conn);
    let tokens: Vec<serde_json::Value> = rows.into_iter().map(|mut token| {
        if let Some(output_id) = token["outputId"].as_i64() {
            if let Ok(tags) = tag_repo.get_tags_for_output(output_id) {
                token["tags"] = serde_json::json!(tags);
            }
        }
        token
    }).collect();

    HttpResponse::Ok().json(serde_json::json!({
        "tokens": tokens,
        "count": tokens.len(),
    }))
}

/// Request structure for /relinquishOutput endpoint
#[derive(Debug, Deserialize)]
pub struct RelinquishOutputRequest {
    pub basket: String,
    pub output: String,  // Outpoint string "txid.vout"
}

/// POST /relinquishOutput - BRC-100 Call Code 7
/// Removes an output from a basket (stops tracking it)
pub async fn relinquish_output(
    state: web::Data<AppState>,
    http_req: HttpRequest,
    body: web::Bytes,
) -> HttpResponse {
    log::info!("📋 /relinquishOutput called");

    // Phase 2.6-D scoped-grant gate (basket access, read_write — destructive).
    if let Some(basket_name) = peek_scoped_grant_scope_basket(&body) {
        let outcome = crate::permission_service::dispatch_scoped_grant(
            &state.permission,
            &state.database,
            state.current_user_id,
            &http_req,
            &body,
            "/relinquishOutput",
            crate::permission_service::ScopedCall::Basket {
                basket: &basket_name,
                access: "read_write",
            },
        );
        if let crate::permission_service::GateOutcome::EarlyReturn(resp) = outcome {
            return resp;
        }
    }

    // Defense-in-depth: verify domain is approved
    {
        let db = state.database.lock().unwrap();
        if let Err(resp) = check_domain_approved(&http_req, db.connection(), state.current_user_id) {
            return resp;
        }
    }

    let req: RelinquishOutputRequest = match serde_json::from_slice(&body) {
        Ok(r) => r,
        Err(e) => {
            log::error!("   Failed to parse RelinquishOutputRequest: {}", e);
            return HttpResponse::BadRequest().json(serde_json::json!({
                "error": format!("Invalid request: {}", e)
            }));
        }
    };

    log::info!("   Basket: {}", req.basket);
    log::info!("   Output: {}", req.output);

    // Phase 2.6-D D.3: protected basket guardrail in the endpoint itself.
    if crate::permission_service::is_protected_basket(&req.basket.trim().to_lowercase()) {
        return HttpResponse::BadRequest().json(serde_json::json!({
            "error": "Basket name is reserved and cannot be modified via relinquishOutput",
        }));
    }

    // Parse outpoint
    let parts: Vec<&str> = req.output.split('.').collect();
    if parts.len() != 2 {
        return HttpResponse::BadRequest().json(serde_json::json!({
            "error": "Invalid outpoint format. Expected 'txid.vout'"
        }));
    }

    let txid = parts[0];
    let vout: i32 = match parts[1].parse() {
        Ok(v) => v,
        Err(_) => {
            return HttpResponse::BadRequest().json(serde_json::json!({
                "error": "Invalid vout value"
            }));
        }
    };

    let db = state.database.lock().unwrap();
    let basket_repo = crate::database::BasketRepository::new(db.connection());
    let output_repo = crate::database::OutputRepository::new(db.connection());

    // Resolve basket
    let basket_id = match basket_repo.find_by_name(&req.basket) {
        Ok(Some(basket)) => basket.id.unwrap(),
        Ok(None) => {
            return HttpResponse::NotFound().json(serde_json::json!({
                "error": format!("Basket '{}' not found", req.basket)
            }));
        }
        Err(e) => {
            log::error!("   Failed to find basket: {}", e);
            return HttpResponse::InternalServerError().json(serde_json::json!({
                "error": format!("Failed to find basket: {}", e)
            }));
        }
    };

    // Phase 4D: Find output from outputs table (PRIMARY SOURCE)
    let db_output = match output_repo.get_by_txid_vout(txid, vout as u32) {
        Ok(Some(o)) => o,
        Ok(None) => {
            return HttpResponse::NotFound().json(serde_json::json!({
                "error": format!("Output {} not found", req.output)
            }));
        }
        Err(e) => {
            log::error!("   Failed to find output: {}", e);
            return HttpResponse::InternalServerError().json(serde_json::json!({
                "error": format!("Failed to find output: {}", e)
            }));
        }
    };

    // Verify output is in the specified basket
    if db_output.basket_id != Some(basket_id) {
        return HttpResponse::BadRequest().json(serde_json::json!({
            "error": format!("Output {} is not in basket '{}'", req.output, req.basket)
        }));
    }

    // Remove output from basket
    let output_id = db_output.output_id.unwrap();
    if let Err(e) = output_repo.remove_from_basket(output_id) {
        log::error!("   Failed to remove output from basket: {}", e);
        return HttpResponse::InternalServerError().json(serde_json::json!({
            "error": format!("Failed to remove output from basket: {}", e)
        }));
    }

    log::info!("   ✅ Output {} removed from basket '{}'", req.output, req.basket);
    drop(db);
    HttpResponse::Ok().json(serde_json::json!({
        "relinquished": true
    }))
}

/// Request structure for /getHeaderForHeight endpoint
#[derive(Debug, Deserialize)]
pub struct GetHeaderForHeightRequest {
    pub height: u32,
}

/// POST /getHeight - BRC-100 Call Code 25
/// Returns the chain tip — the wallet's own verified tip (B5-T1-P7a-1), never an indexer's claim.
/// Before the first header sync of this process reaches a source's tip, the only tip held is the
/// compiled checkpoint's (months stale), so the answer is an error, never a height and never 0.
pub async fn get_height(state: web::Data<AppState>, _body: web::Bytes) -> HttpResponse {
    log::info!("📋 /getHeight called");
    if !state.chain_tracker.is_synced() {
        log::warn!("   Block headers not synced yet — no verified tip to report");
        return HttpResponse::ServiceUnavailable().json(serde_json::json!({
            "error": "The wallet's block headers are not synced yet; try again shortly"
        }));
    }
    let height = state.chain_tracker.current_height();
    log::info!("   Verified chain tip: {}", height);
    HttpResponse::Ok().json(serde_json::json!({
        "height": height
    }))
}

/// POST /getHeaderForHeight - BRC-100 Call Code 26
/// Returns the 80-byte block header at a height from the wallet's own verified chain (B5-T1-P7a-1).
/// A height the chain does not hold (above the tip, or below the compiled checkpoint) is an error,
/// never an empty header and never an unchecked indexer answer.
pub async fn get_header_for_height(
    state: web::Data<AppState>,
    req: web::Json<GetHeaderForHeightRequest>,
) -> HttpResponse {
    log::info!("📋 /getHeaderForHeight called");
    log::info!("   Height: {}", req.height);
    match state.chain_tracker.header_for_height(req.height) {
        Some(header) => HttpResponse::Ok().json(serde_json::json!({
            "header": hex::encode(header)
        })),
        None => {
            let tip = state.chain_tracker.current_height();
            let reason = if req.height > tip {
                format!("Height {} is above the wallet's verified tip ({})", req.height, tip)
            } else {
                format!("Height {} is below the wallet's header checkpoint ({})", req.height, state.chain_tracker.checkpoint_height())
            };
            log::warn!("   {}", reason);
            HttpResponse::NotFound().json(serde_json::json!({ "error": reason }))
        }
    }
}

/// POST /getNetwork - BRC-100 Call Code 27
/// Returns the network name ("mainnet" or "testnet")
pub async fn get_network(_body: web::Bytes) -> HttpResponse {
    log::info!("📋 /getNetwork called");

    // For now, return hardcoded "mainnet"
    // TODO: Could read from config file or environment variable later
    HttpResponse::Ok().json(serde_json::json!({
        "network": "mainnet"
    }))
}

/// POST /wallet/cleanup - Scan and remove ghost UTXOs
///
/// Checks all unspent UTXOs against the blockchain and removes any that
/// don't exist on-chain (ghost UTXOs from failed broadcasts).
pub async fn wallet_cleanup(state: web::Data<AppState>, _body: web::Bytes) -> HttpResponse {
    log::info!("🧹 /wallet/cleanup called - scanning for ghost UTXOs...");

    // Get all unspent UTXOs
    let unspent_utxos: Vec<(String, u32, i64, i64)> = {
        let db = state.database.lock().unwrap();
        let conn = db.connection();

        let mut stmt = match conn.prepare(
            "SELECT txid, vout, satoshis, user_id FROM outputs WHERE spendable = 1"
        ) {
            Ok(s) => s,
            Err(e) => {
                log::error!("   Failed to query UTXOs: {}", e);
                return HttpResponse::InternalServerError().json(serde_json::json!({
                    "error": format!("Database error: {}", e)
                }));
            }
        };

        stmt.query_map([], |row| {
            Ok((
                row.get::<_, String>(0)?,
                row.get::<_, u32>(1)?,
                row.get::<_, i64>(2)?,
                row.get::<_, i64>(3)?,
            ))
        })
        .map(|rows| rows.filter_map(|r| r.ok()).collect())
        .unwrap_or_default()
    };

    log::info!("   Found {} unspent UTXOs to check", unspent_utxos.len());

    let mut checked = 0;
    let mut ghosts_removed = 0;
    let mut ghost_sats = 0i64;
    let mut valid_count = 0;
    let mut valid_sats = 0i64;

    // Check unique txids (multiple UTXOs can share same txid with different vouts)
    let mut unchecked = 0;
    let mut unchecked_sats = 0i64;
    let mut checked_txids: std::collections::HashMap<String, ChainPresence> = std::collections::HashMap::new();

    for (txid, vout, satoshis, _address_id) in &unspent_utxos {
        checked += 1;

        // Cache the on-chain check per txid
        let presence = if let Some(cached) = checked_txids.get(txid) {
            cached.clone()
        } else {
            let result = chain_presence_verdict(state.services.tx_status_unanimous(txid).await);
            checked_txids.insert(txid.clone(), result.clone());
            result
        };

        // ⛔ B5-T1-P2 (P2-A10/A11): mark a ghost ONLY on a positive "every provider
        // says it does not exist". An error, `Unknown`, orphan/stale or rejected answer
        // is not evidence of absence — it used to read as "absent" here
        // (`.unwrap_or(false)` over a helper that already mapped Unknown ⇒ false) and
        // write a durable `ghost-cleanup` over a real coin.
        if let ChainPresence::CouldNotTell(ref why) = presence {
            unchecked += 1;
            unchecked_sats += satoshis;
            log::warn!("   ❔ Could not check {}:{} ({} sats) — left untouched: {}",
                &txid[..std::cmp::min(16, txid.len())], vout, satoshis, why);
            continue;
        }

        if presence == ChainPresence::Present {
            valid_count += 1;
            valid_sats += satoshis;
        } else {
            ghosts_removed += 1;
            ghost_sats += satoshis;
            log::warn!("   👻 Ghost UTXO: {}:{} ({} sats)", &txid[..std::cmp::min(16, txid.len())], vout, satoshis);

            // Mark as spent
            let db = state.database.lock().unwrap();
            let output_repo = crate::database::OutputRepository::new(db.connection());
            let _ = output_repo.mark_spent(txid, *vout, "ghost-cleanup");
        }
    }

    log::info!("   🧹 Cleanup complete: {} checked, {} valid ({} sats), {} ghosts removed ({} sats), {} could not be checked ({} sats)",
              checked, valid_count, valid_sats, ghosts_removed, ghost_sats, unchecked, unchecked_sats);

    HttpResponse::Ok().json(serde_json::json!({
        "checked": checked,
        "valid": valid_count,
        "validSats": valid_sats,
        "ghostsRemoved": ghosts_removed,
        "ghostSats": ghost_sats,
        "unchecked": unchecked,
        "uncheckedSats": unchecked_sats,
    }))
}

/// What the chain says about one txid, for a caller that makes a **destructive**
/// write on "absent" (B5-T1-P2). Three-way on purpose: `check_tx_exists_on_chain`
/// collapses "could not tell" into `false`, which is safe for callers that
/// rebroadcast on absent and wrong for one that writes.
/// ⭐ T4-P1 should adopt this rather than add a second strict reader.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum ChainPresence {
    Present,
    /// Every provider in the chain answered "not found" (`tx_status_unanimous`).
    Absent,
    CouldNotTell(String),
}

/// Read one `tx_status_unanimous` answer. `Absent` only on the `NotFound`
/// **variant** — never on error text, an `Unknown` state, an ARC orphan/stale
/// status, or a rejection (none of those says the transaction does not exist).
pub(crate) fn chain_presence_verdict(
    result: Result<crate::services::TxStatus, crate::services::IndexerError>,
) -> ChainPresence {
    use crate::services::{IndexerError, TxState};
    match result {
        Err(IndexerError::NotFound) => ChainPresence::Absent,
        Err(e) => ChainPresence::CouldNotTell(e.to_string()),
        Ok(status) => {
            if let Some(raw) = status.raw_provider_status.as_deref() {
                if raw == "SEEN_IN_ORPHAN_MEMPOOL" || raw == "MINED_IN_STALE_BLOCK" {
                    return ChainPresence::CouldNotTell(raw.to_string());
                }
            }
            match status.state {
                TxState::Mined | TxState::InMempool => ChainPresence::Present,
                other => ChainPresence::CouldNotTell(format!("state {:?}", other)),
            }
        }
    }
}

